package com.sledge.browser.gate

// Generated by the desktop mirror. The build hook refreshes this file.

enum class PlatformPermission(val label: String, val androidName: String) {
    Camera("the camera", "android.permission.CAMERA"),
    CoarseLocation("approximate location", "android.permission.ACCESS_COARSE_LOCATION"),
    FineLocation("precise location", "android.permission.ACCESS_FINE_LOCATION"),
    Microphone("the microphone", "android.permission.RECORD_AUDIO"),
}

/** Android asks with a runtime request. Desktop asks with a window prompt. */
interface PermissionGate {
    fun ask(permission: PlatformPermission, onResult: (Boolean) -> Unit)
}
